<?php declare(strict_types=1);namespace App\Models;use App\Core\DB;use App\Core\QueryBuilder;abstract class Model{protected static string $table='';protected static array $json=[];protected static bool $timestamps=true;public static function table():string{return static::$table;}public static function query():QueryBuilder{return DB::from(static::$table);}public static function find(int $H):?array{return static::cast(static::query()->where('id',$H)->first());}public static function findBy(string $b,mixed $W):?array{return static::cast(static::query()->where($b,$W)->first());}public static function all(string $b='id',string $C='ASC'):array{return static::castAll(static::query()->orderBy($b,$C)->get());}public static function where(string $w,mixed $W):array{return static::castAll(static::query()->where($w,$W)->get());}public static function create(array $g):int{if(static::$timestamps&&!isset($g['created_at'])){$g['created_at']=now();}return DB::insert(static::$table,$g);}public static function update(int $u,array $a):int{if(static::$timestamps&&!isset($a['updated_at'])){$a['updated_at']=now();}return DB::update(static::$table,$a,'id = ?',[$u]);}public static function delete(int $W):int{return DB::delete(static::$table,'id = ?',[$W]);}public static function count():int{return static::query()->count();}public static function cast(?array $a):?array{if($a===null){return null;}foreach(static::$json as $c){if(array_key_exists($c,$a)&&is_string($a[$c])){$f=json_decode($a[$c],true);$a[$c]=is_array($f)?$f:($a[$c]===''||$a[$c]===null?[]:$f);}}return $a;}public static function castAll(array $s):array{return array_map(fn($u)=>static::cast($u),$s);}}